package cz.mh.rallye.rallye_backend.races;
import java.util.*;import org.junit.jupiter.api.Test;import jakarta.servlet.http.Cookie;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
import cz.mh.rallye.rallye_backend.races.api.EventController;import cz.mh.rallye.rallye_backend.races.application.EventService;import cz.mh.rallye.rallye_backend.identity.api.*;import cz.mh.rallye.rallye_backend.identity.application.*;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
@WebMvcTest(EventController.class) @Import({AuthConfiguration.class,AuthCookies.class,ApiErrors.class})
class EventHttpTest {
 @Autowired MockMvc mvc;@MockitoBean AuthService auth;@MockitoBean EventService service;
 final UUID id=UUID.randomUUID();final String secret=new SecretTokens().create();final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);
 void login(boolean admin){when(auth.authenticate(secret)).thenReturn(actor);when(auth.isAdministrator(actor)).thenReturn(admin);}
 String body(){return "{\"templateVersion\":4,\"name\":\"Event\",\"scheduledStartAt\":\"2026-11-01T10:00:00Z\",\"endAt\":\"2026-11-01T16:00:00Z\"}";}
 @Test void readRoutesAreAdminOnly()throws Exception{for(String suffix:List.of("","/"+id,"/"+id+"/stages","/"+id+"/stages/"+UUID.randomUUID(),"/"+id+"/files","/"+id+"/files/map.png")){mvc.perform(get("/api/v1/race-events"+suffix)).andExpect(status().isUnauthorized());login(false);mvc.perform(get("/api/v1/race-events"+suffix).header("Authorization","Bearer "+secret)).andExpect(status().isForbidden());}verifyNoInteractions(service);}
 @Test void createsUsingBearerAndReturnsLocation()throws Exception{login(true);when(service.create(eq(actor),eq(id),eq(4L),any(),any())).thenReturn(new EventService.Created(id,0));mvc.perform(post("/api/v1/race-templates/"+id+"/events").header("Authorization","Bearer "+secret).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isCreated()).andExpect(header().string("Location","/api/v1/race-events/"+id)).andExpect(jsonPath("$.version").value(0));}
 @Test void cookieRequiresCsrf()throws Exception{login(true);mvc.perform(post("/api/v1/race-templates/"+id+"/events").cookie(new Cookie(AuthCookies.NAME,secret)).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void cookieWithCsrfCanCreate()throws Exception{login(true);when(service.create(eq(actor),eq(id),eq(4L),any(),any())).thenReturn(new EventService.Created(id,0));mvc.perform(post("/api/v1/race-templates/"+id+"/events").cookie(new Cookie(AuthCookies.NAME,secret)).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body())).andExpect(status().isCreated());}
 @Test void unknownFieldsInvalidVersionAndMissingKeyAre400()throws Exception{login(true);for(String input:List.of(body().replace("4,","4.5,"),body().replace("4,","9223372036854775808,"),body().replace("\"name\":","\"status\":\"RUNNING\",\"name\":"))){mvc.perform(post("/api/v1/race-templates/"+id+"/events").header("Authorization","Bearer "+secret).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(input)).andExpect(status().isBadRequest());}mvc.perform(post("/api/v1/race-templates/"+id+"/events").header("Authorization","Bearer "+secret).contentType("application/json").content(body())).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void pdfUsesAttachmentAndPrivacyHeaders()throws Exception{login(true);when(service.file(actor,id,"rules.pdf")).thenReturn(new EventService.Content("rules.pdf","application/pdf","%PDF-1.4".getBytes(),false,true));mvc.perform(get("/api/v1/race-events/"+id+"/files/rules.pdf").header("Authorization","Bearer "+secret)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Referrer-Policy","no-referrer")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.startsWith("attachment")));}
 @Test void noStartRegistrationRoutesExistButDeleteRequiresVersion()throws Exception{login(true);mvc.perform(post("/api/v1/race-events/"+id+"/start").header("Authorization","Bearer "+secret)).andExpect(status().isNotFound());mvc.perform(delete("/api/v1/race-events/"+id).header("Authorization","Bearer "+secret)).andExpect(status().isBadRequest());}
 @Test void deleteRequiresAdminCsrfAndVersion()throws Exception{login(false);mvc.perform(delete("/api/v1/race-events/"+id).param("version","3").header("Authorization","Bearer "+secret)).andExpect(status().isForbidden());login(true);mvc.perform(delete("/api/v1/race-events/"+id).param("version","3").cookie(new Cookie(AuthCookies.NAME,secret))).andExpect(status().isForbidden());mvc.perform(delete("/api/v1/race-events/"+id).param("version","3").header("Authorization","Bearer "+secret)).andExpect(status().isNoContent());verify(service).delete(actor,id,3);}
 @Test void offsetMinuteInputHasNoUnintendedTimeShift()throws Exception{login(true);when(service.create(eq(actor),eq(id),eq(4L),any(),any())).thenReturn(new EventService.Created(id,0));String input=body().replace("10:00:00Z","11:00:00+01:00").replace("16:00:00Z","17:00:00+01:00");mvc.perform(post("/api/v1/race-templates/"+id+"/events").header("Authorization","Bearer "+secret).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(input)).andExpect(status().isCreated());var cap=org.mockito.ArgumentCaptor.forClass(EventService.Input.class);verify(service).create(eq(actor),eq(id),eq(4L),any(),cap.capture());org.junit.jupiter.api.Assertions.assertEquals(java.time.Instant.parse("2026-11-01T10:00:00Z"),cap.getValue().scheduledStartAt());}


 @Test void instructionsResponseAndNullFollowContract()throws Exception{login(true);UUID stage=UUID.randomUUID();String url="/api/v1/race-events/"+id+"/stages/"+stage+"/instructions";when(service.updateInstructions(actor,id,stage,3,"# New")).thenReturn(new EventService.InstructionsView(id,stage,4,"# New","<h1 id=\"new\">New</h1>",List.of()));mvc.perform(put(url).header("Authorization","Bearer "+secret).contentType("application/json").content("{\"version\":3,\"instructionsMarkdown\":\"# New\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.raceEventId").value(id.toString())).andExpect(jsonPath("$.stageId").value(stage.toString())).andExpect(jsonPath("$.version").value(4)).andExpect(jsonPath("$.instructionsMarkdown").value("# New")).andExpect(jsonPath("$.missingReferences").isEmpty());mvc.perform(put(url).header("Authorization","Bearer "+secret).contentType("application/json").content("{\"version\":3,\"instructionsMarkdown\":null}")).andExpect(status().isOk());verify(service).updateInstructions(actor,id,stage,3,null);}
 @Test void instructionsStrictBodyValidation()throws Exception{login(true);String url="/api/v1/race-events/"+id+"/stages/"+UUID.randomUUID()+"/instructions";for(String body:List.of("{}","{\"version\":0}","{\"version\":0,\"instructionsMarkdown\":7}","{\"version\":-1,\"instructionsMarkdown\":null}","{\"version\":0.5,\"instructionsMarkdown\":null}","{\"version\":0,\"instructionsMarkdown\":null,\"name\":\"Other\"}"))mvc.perform(put(url).header("Authorization","Bearer "+secret).contentType("application/json").content(body)).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void instructionsRequireAdminAndCookieCsrf()throws Exception{String url="/api/v1/race-events/"+id+"/stages/"+UUID.randomUUID()+"/instructions",body="{\"version\":0,\"instructionsMarkdown\":\"Text\"}";mvc.perform(put(url).contentType("application/json").content(body).with(csrf())).andExpect(status().isUnauthorized());login(false);mvc.perform(put(url).header("Authorization","Bearer "+secret).contentType("application/json").content(body)).andExpect(status().isForbidden());login(true);mvc.perform(put(url).cookie(new Cookie(AuthCookies.NAME,secret)).contentType("application/json").content(body)).andExpect(status().isForbidden());verifyNoInteractions(service);mvc.perform(put(url).cookie(new Cookie(AuthCookies.NAME,secret)).with(csrf().asHeader()).contentType("application/json").content(body)).andExpect(status().isOk());}
 @Test void instructionsVersionConflictUsesExistingErrorFormat()throws Exception{login(true);UUID stage=UUID.randomUUID();when(service.updateInstructions(actor,id,stage,3,"Text")).thenThrow(new AuthFailure(409,"RACE_EVENT_VERSION_CONFLICT"));mvc.perform(put("/api/v1/race-events/"+id+"/stages/"+stage+"/instructions").header("Authorization","Bearer "+secret).contentType("application/json").content("{\"version\":3,\"instructionsMarkdown\":\"Text\"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("RACE_EVENT_VERSION_CONFLICT"));}
}
